/* Brick & Decor PWA v0.8 L1.3 UX + Stability Patch
   Applied on top of v0.7 Case-Centric Test. Frontend-only test build. */

const V08_LOGOS = {
  CO1: 'data:image/jpeg;base64,',
  CO2: 'data:image/png;base64,',
  CO3: 'data:image/png;base64,',
  CO4: 'data:image/jpeg;base64,'
};
const V08_SUPPLIER_PREVIEWS = {};
let v08HistoryReady = false;
let v08HistoryRestoring = false;
let v08LastRouteSig = '';

function v08Clone(x){ return JSON.parse(JSON.stringify(x)); }
function v08Norm(x){ return String(x||'').trim().toLowerCase().replace(/\s+/g,' '); }
function v08Options(items,value=''){
  return items.map(x=>{
    const o = typeof x==='string' ? {value:x,label:x} : x;
    return `<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`;
  }).join('');
}
function v08Select(id,label,items,value='',full=''){
  return `<div class="field ${full}"><label>${esc(label)}</label><select id="${id}">${v08Options(items,value)}</select></div>`;
}
function v08TextArea(id,label,value='',full='full'){
  return `<div class="field ${full}"><label>${esc(label)}</label><textarea id="${id}">${esc(value)}</textarea></div>`;
}
function v08RoleLabel(u){ return `${u.name} — ${u.role}`; }
function v08PropertyFromLegacy(p){
  const t=String(p.propertyType||p.type||'').toLowerCase();
  if(t.includes('hdb')) return 'HDB';
  if(t.includes('condo')) return 'Condo';
  if(t.includes('landed')) return 'Landed';
  if(t.includes('commercial')) return 'Commercial';
  if(t.includes('office')) return 'Office';
  if(t.includes('retail')) return 'Retail';
  return p.propertyType||'Other';
}
function v08LegacySnapshot(q,v){
  return {
    v:v.v,date:v.date,template:v.template,total:Number(v.total||0),by:v.by,
    clientMeta:v08Clone(q.clientMeta||{}),items:v08Clone(q.items||[]),discount:Number(q.discount||0),
    subtotal:Number(qtot(q)||0),gst:Number(qgst(q)||0),
    companySnapshot:v08CompanySnapshot(co(q.co)),legacy:true,
    legacyNote:'This revision existed before full immutable line-item snapshots were stored in v0.8. The original revision metadata and total are preserved; current demo item wording is shown only to make the historical preview viewable.'
  };
}
function v08CompanySnapshot(c){
  return {name:c.name,uen:c.uen,gst:c.gst,gstRate:Number(c.gstRate||0),addr:c.addr,email:c.email,phone:c.phone,bank:c.bank,paynow:c.paynow,logo:c.logo,docs:v08Clone(c.docs||defaultDocTemplates())};
}
function v08Upgrade(){
  S.settings.propertyTypes=S.settings.propertyTypes||['HDB','Condo','Landed','Commercial','Office','Retail','Other'];
  S.settings.scopeSections=S.settings.scopeSections||['Professional Services','Hacking Works','Masonry Works','Floor Works','Carpentry Works','Electrical Works','Plumbing Works','Painting Works','Window Works','Miscellaneous Works'];
  S.companies.forEach(c=>{
    if(V08_LOGOS[c.id]) c.logo=V08_LOGOS[c.id];
    c.docs=c.docs||defaultDocTemplates();
    c.paynowVerified=(c.paynowVerified!==undefined?c.paynowVerified:(c.paynow===c.uen));
  });
  S.projects.forEach(p=>{
    p.propertyType=p.propertyType||v08PropertyFromLegacy(p);
    p.activity=p.activity||[];
    p.adjustments=p.adjustments||[];
    p.assigned=Array.isArray(p.assigned)?p.assigned.filter(Boolean):[];
  });
  S.costs.forEach(c=>{
    if(!c.source)c.source=c.sourceInvoice?'AUTO':'MANUAL';
    c.date=c.date||'';c.paidTo=c.paidTo||c.supplier||'';c.reference=c.reference||c.invoice||'';c.remark=c.remark||'';
  });
  S.quotes.forEach(q=>{
    q.versionSnapshots=q.versionSnapshots||[];
    q.clientMeta=q.clientMeta||{};
    q.versions=q.versions||[];
    q.versions.forEach(v=>{
      if(!q.versionSnapshots.some(s=>s.v===v.v))q.versionSnapshots.push(v08LegacySnapshot(q,v));
    });
  });
  S.vos.forEach(v=>{
    const q=caseQuotes(v.p).slice(-1)[0];
    v.originalQuoteId=v.originalQuoteId||q?.id||'';
    v.originalAmount=Number(v.originalAmount||(q?quoteContractTotal(q):0));
    v.history=v.history||[{date:v.date||today(),by:'System',action:'VO migrated',detail:v.reason||''}];
    (v.items||[]).forEach(i=>{i.type=i.type||'Additional';i.area=i.area||'Unassigned Area';i.section=i.section||'General Works';i.desc=i.desc||'';i.unit=i.unit||'Lot';i.cost=Number(i.cost||0);i.price=Number(i.price||0);i.qty=Number(i.qty||1);i.pricingType=i.pricingType||'Amount';});
  });
  S.dos.forEach(d=>{
    d.date=d.date||today();d.acknowledged=!!d.acknowledged;d.consultantSignature=d.consultantSignature||'';d.managerSignature=d.managerSignature||'';
  });
  save();
}

logoUrl = function(path){ return path||''; };

function v08Route(){return {active,qDetail,pDetail,caseDetail,caseSub,sub,poSub,invSub};}
function v08RouteSig(r){return JSON.stringify(r);}
function v08ApplyRoute(r){
  active=r.active||'dashboard';qDetail=r.qDetail||'';pDetail=r.pDetail||'';caseDetail=r.caseDetail||'';
  caseSub=r.caseSub||'overview';sub=r.sub||'cost';poSub=r.poSub||'All';invSub=r.invSub||'All';
}
show = function(t){
  active=t||active;
  const route=v08Route(), sig=v08RouteSig(route);
  if(!v08HistoryRestoring){
    if(!v08HistoryReady){history.replaceState({bdRoute:route},'',location.pathname+location.search+location.hash);v08HistoryReady=true;}
    else if(sig!==v08LastRouteSig){history.pushState({bdRoute:route},'',location.pathname+location.search+location.hash);}
  }
  layout();
  const renderer=P[active];
  $('content').innerHTML=renderer?renderer():`<div class="card"><h3>Page unavailable</h3><p class="small">This screen could not be rendered.</p></div>`;
  save();v08LastRouteSig=v08RouteSig(v08Route());
};
openTab = function(t){active=t;filters={};qDetail='';pDetail='';caseDetail='';caseSub='overview';sub='cost';show(t);};
function openCase(pid,tab='overview'){caseDetail=pid;caseSub=tab;qDetail='';pDetail='';show('cases');}
function openQuote(qid){qDetail=qid;show('quotation');}
window.addEventListener('popstate',e=>{
  if(!e.state||!e.state.bdRoute)return;
  v08HistoryRestoring=true;v08ApplyRoute(e.state.bdRoute);layout();
  const renderer=P[active];$('content').innerHTML=renderer?renderer():'<div class="card">Page unavailable.</div>';save();
  v08LastRouteSig=v08RouteSig(v08Route());v08HistoryRestoring=false;
});

fb = function(kind){
  let cos=S.companies.filter(c=>canCo(c.id)),us=S.users,ps=S.projects.filter(canP);
  let sts={quotation:['Draft','Sent','Follow-up Required','Accepted'],projects:['Quotation Draft','Quotation Sent','Project Confirmed','Work In Progress','Closure Requested','Closed'],invoices:['Unpaid','Partially Paid','Overdue','Paid'],po:['Pending Verification','Approved','Rejected / Disputed','Partial','Paid','Duplicate Warning','Overdue'],profit:['Pending Superadmin Approval','Approved','Paid']};
  return `<div class="bar"><div class="filters"><select onchange="setF('co',this.value)"><option value="">All Companies</option>${cos.map(c=>`<option value="${c.id}" ${filters.co===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select onchange="setF('worker',this.value)"><option value="">All Workers</option>${us.map(u=>`<option value="${u.id}" ${filters.worker===u.id?'selected':''}>${esc(v08RoleLabel(u))}</option>`).join('')}</select><select onchange="setF('project',this.value)"><option value="">All Cases / Projects</option>${ps.map(p=>`<option value="${p.id}" ${filters.project===p.id?'selected':''}>${esc(p.client)} — ${esc(p.site||p.name)}</option>`).join('')}</select><input type="date" value="${filters.from||''}" onchange="setF('from',this.value)"><input type="date" value="${filters.to||''}" onchange="setF('to',this.value)"><select onchange="setF('status',this.value)"><option value="">All Status</option>${(sts[kind]||[]).map(s=>`<option ${filters.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><br><button class="btn s" onclick="clearF()">Clear Filters</button> <span class="small">Company / worker / case / date / status</span></div>`;
};

